import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const i="/assets/image%20(64).CPFUCZKa.png",s="/assets/image%20(65).DNSSED9q.png",n="/assets/image%20(66).BtDR4zL_.png",p="/assets/image%20(67).BC5rdvpp.png",d="/assets/image%20(68).C9fdghE0.png",l="/assets/image%20(69).Gss3fc9T.png",m="/assets/image%20(70).BsUNPbyp.png",c="/assets/image%20(71).DqbOWysv.png",g="/assets/image%20(72).C-vX0hwb.png",u="/assets/image%20(73).B1vREz26.png",h="/assets/image%20(76).DI2HaXoj.png",f="/assets/image%20(78).Bmbt46vg.png",b="/assets/image%20(79).46cJye-g.png",k="/assets/image%20(80).CuBDVY81.png",y="/assets/image%20(81).YG_8Slk2.png",A="/assets/Amibroker%20Chart.dWI181fL.png",I=JSON.parse('{"title":"AmiQuotes","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/amibroker/amiquotes.md","filePath":"trading-platform/amibroker/amiquotes.md"}'),_={name:"trading-platform/amibroker/amiquotes.md"};function T(q,e,w,v,S,D){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="amiquotes" tabindex="-1">AmiQuotes <a class="header-anchor" href="#amiquotes" aria-label="Permalink to &quot;AmiQuotes&quot;">​</a></h1><p><strong>This tool helps you to fetch data (1 minute / Daily) directly from the broker and seamlessly update Amibroker using the AmiQuote tool every minute.</strong></p><p>AmiQuote is a polling downloader, not a streaming feed. The <code>Tradeboard.ads</code> file below is an AmiQuote data-source definition: each time AmiQuote runs it issues one HTTP GET per symbol against the Tradeboard <a href="./../../api-documentation/v1/data-api/ticker.html">Ticker API</a> and imports the plain-text result into the AmiBroker database.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET http://127.0.0.1:5000/api/v1/ticker/{symbol}?apikey={api_key}&amp;interval={interval}&amp;from={from}&amp;to={to}&amp;format=txt</span></span></code></pre></div><p>Two consequences worth knowing before you start:</p><ul><li>The data source declares only two usable intervals: <strong>Daily</strong> (<code>interval=D</code>, up to 3650 days per request) and <strong>1-minute</strong> (<code>interval=1m</code>, 1 day per request). The other periodicities listed by AmiQuote carry no Tradeboard interval token and will not download.</li><li>The Ticker API clamps the requested date range server side: intraday intervals are capped at 30 days back from the end date, and D/W/M at 10 years. Longer requests are silently trimmed rather than rejected.</li></ul><p>If you want a live tick feed and realtime charts instead of a once-a-minute snapshot import, use the <a href="./amibroker-plugin.html">Tradeboard AmiBroker Plugin</a>, which streams from the Tradeboard WebSocket proxy.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Tradeboard and Tradeboard API Key</p><p>Amibroker 6.0 or higher</p><p>Amiquotes 4.10 or higher (mostly preinstalled with Amibroker) if not download from <a href="https://amibroker.com/download.html" target="_blank" rel="noreferrer">Amibroker Download section</a></p><p>Tradeboard supported Brokers providing Historical Data / Intraday Data API</p><p>Note : As of now kotak not supporting intraday/historical data API</p><h3 id="step-1-download-tradeboard-amiquotes-plugin" tabindex="-1">Step 1 : Download Tradeboard - Amiquotes (Plugin) <a class="header-anchor" href="#step-1-download-tradeboard-amiquotes-plugin" aria-label="Permalink to &quot;Step 1 : Download Tradeboard - Amiquotes (Plugin)&quot;">​</a></h3><p><a href="./../../.gitbook/assets/Tradeboard.ads.html">Download File</a></p><p>Download the file and save under <strong>Amibroker -&gt; Amiquotes -&gt; DataSource Folder</strong></p><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><h3 id="step-2-create-the-amibroker-database" tabindex="-1">Step 2 : Create the Amibroker Database <a class="header-anchor" href="#step-2-create-the-amibroker-database" aria-label="Permalink to &quot;Step 2 : Create the Amibroker Database&quot;">​</a></h3><p>Open Amibroker Goto File Menu -&gt; New -&gt; Database</p><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><p>Create a New Database</p><p>Enter the Database Name, Base Time Interval and Click Create</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><p>Enter the Database Source as (local database) and Number of Bars as 75000</p><figure><img src="'+p+'" alt=""><figcaption></figcaption></figure><p>Now click on Intraday Settings and Enable Allow Mixed EOD/Interval data and press ok</p><figure><img src="'+d+'" alt=""><figcaption></figcaption></figure><h3 id="step-3-add-tradeboard-ticker-symbols" tabindex="-1">Step 3 : Add Tradeboard Ticker Symbols <a class="header-anchor" href="#step-3-add-tradeboard-ticker-symbols" aria-label="Permalink to &quot;Step 3 : Add Tradeboard Ticker Symbols&quot;">​</a></h3><p>Add Ticker Symbols from the Symbols menu -&gt; New</p><p>The AmiBroker ticker name is pasted straight into the Ticker API path, so it must be written as <code>EXCHANGE:SYMBOL</code>, for example <code>NSE:RELIANCE</code>, <code>BSE:TCS</code>, <code>MCX:CRUDEOIL18JUN26FUT</code>, <code>NSE_INDEX:NIFTY</code>. This is the reverse of the <code>SYMBOL-EXCHANGE</code> format used by the Tradeboard AmiBroker data plugin. A ticker with no <code>EXCHANGE:</code> prefix does not fail cleanly: the Ticker API falls back to <code>NSE:RELIANCE</code> and you will silently import the wrong instrument.</p><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><p>You can Also add the ticker symbol with comma separated</p><figure><img src="'+m+'" alt=""><figcaption></figcaption></figure><p>If you want to import bulk symbols consider using Watchlist import method (Supports .txt or .csv or .tls format)</p><figure><img src="'+c+'" alt=""><figcaption></figcaption></figure><h3 id="step-4-amiquote-realtime-update" tabindex="-1">Step 4 : Amiquote Realtime Update <a class="header-anchor" href="#step-4-amiquote-realtime-update" aria-label="Permalink to &quot;Step 4 : Amiquote Realtime Update&quot;">​</a></h3><p>Open Amiquote from Tools Menu -&gt; Auto-update quotes (AmiQuote)</p><figure><img src="'+g+'" alt=""><figcaption></figcaption></figure><p>From the dropdown of Amiquote Select Tradeboard</p><figure><img src="'+u+'" alt=""><figcaption></figcaption></figure><p>Alternatively, you can also import the tradeboard template using the import method. Goto <strong>Data Source Menu -&gt; Import</strong></p><figure><img src="'+h+'" alt=""><figcaption></figcaption></figure><p>configure the Tradeboard API key</p><p>Get the Tradeboard API Key by visiting <strong>tradeboard -&gt; Dashboard -&gt; Click on Profile Icon -&gt; APIKey</strong></p><p>Create one if you installed tradeboard for the first time. Copy the API key and paste in the User-definable data source -&gt; API Key Section as shown below and press ok</p><figure><img src="'+f+'" alt=""><figcaption></figcaption></figure><p>Now Select the desired interval and set Run every 1min and press the play button</p><figure><img src="'+b+'" alt=""><figcaption></figcaption></figure><p>Now the Data Download from the Broker via Tradeboard Starts</p><figure><img src="'+k+'" alt=""><figcaption></figcaption></figure><p>Now you can see that tradeboard is Auto updating the Amibroker Database every 1 minute</p><figure><img src="'+y+'" alt=""><figcaption></figcaption></figure><p>Make sure that Charts are loaded properly.</p><figure><img src="'+A+'" alt=""><figcaption></figcaption></figure><p>Start using your brokers data for your analysis purpose.<br></p><p>For more details and troubleshooting refer the <a href="./../../api-documentation/v1/data-api/ticker.html">Ticker API</a></p><p>Make sure to login to tradeboard every day to fetch the live intraday/EOD quotes</p>',57)])])}const C=a(_,[["render",T]]);export{I as __pageData,C as default};
